export function registerComponent<P = AnyProps>(key: string, component: ComponentType<P>): void {
  const existing = registry.get(key);
  if (existing) {
    existing.base = component as ComponentType;
  } else {
    registry.set(key, { base: component as ComponentType, overrides: [], hasStackConditions: false });
  }
  notifyRegistryChange();
}
