`addOverride` returns a cleanup closure (identity-based removal, recalculates flags, notifies):
```ts
export function addOverride<P = AnyProps>(key: string, override: Override<P>): () => void {
  let entry = registry.get(key);
  if (!entry) {
    entry = { base: (() => null) as ComponentType, overrides: [], hasStackConditions: false };
    registry.set(key, entry);
  }
  entry.overrides.push(override as Override);
  if (hasStackCondition(override.condition)) entry.hasStackConditions = true;
  entry.overrides.sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0));
  notifyRegistryChange();
  return () => {
    const currentEntry = registry.get(key);
    if (currentEntry) {
      currentEntry.overrides = currentEntry.overrides.filter((o) => o !== override);
      currentEntry.hasStackConditions = currentEntry.overrides.some((o) => hasStackCondition(o.condition));
      notifyRegistryChange();
    }
  };
}
```

