          subject,
          continueDraftId: form.isPrimary ? continueDraftId : undefined,
        });
      }),
    )
  ).flat();
  if (requests.length === 0) {
    toast.error(t("no_answers_to_submit"));
    return;
  }
  submitBatch({ requests });
}, [forms, getStore, subject, continueDraftId, submitBatch, t]);
